import itertools

def is_all_interval(perm):
    diffs = [abs(perm[i] - perm[i+1]) for i in range(11)]
    return len(set(diffs)) == 11 and min(diffs) == 1 and max(diffs) == 11

for perm in itertools.permutations(range(12)):
    if is_all_interval(perm):
        print(perm)
        break
else:
    print("No solution")

def find_all_interval(n=12):
    perm = [0] * n
    used = [False] * n
    diff_used = [False] * n

    def backtrack(pos):
        if pos == n:
            return True
        for num in range(n):
            if used[num]:
                continue
            if pos > 0:
                diff = abs(num - perm[pos-1])
                if diff == 0 or diff_used[diff-1]:
                    continue
                diff_used[diff-1] = True
            perm[pos] = num
            used[num] = True
            if backtrack(pos + 1):
                return True
            used[num] = False
            if pos > 0:
                diff_used[diff-1] = False
        return False

    if backtrack(0):
        return perm
    return None

result = find_all_interval()
print(result)
